font-size: 25px;
color: rgb(8, 8, 63);
@media (max-width: 768px) {
font-size: 18px;
}
`;
const SuccessPage = () => {
return (
<React.Fragment>
<Fade bottom duration={700} distance="60px">
<MessageWrapper>
<Icon.CheckCircle
color="rgb(8, 8, 63)"
style={{ width: 50, height: 50 }}
/>
<SuccessMessage>
MESSAGE SENT SUCCESSFULLY
</SuccessMessage>
</MessageWrapper>
</Fade>
</React.Fragment>
);
};
export default SuccessPage;
Redirecting Users to The Success Page
We will use react-router-dom
to handle
navigation between the form page and
the success page.
Run the following command to install it:
npm install react-router-dom
Open App.js
and replace its contents
with the following:
